import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { authAPI } from '../utils/api';

/* ── Inline SVG logo ── */
const AlphagnitoLogo = ({ size = 36 }) => (
  <svg width={size} height={size} viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg">
    <path d="M100 10 L176 55 L176 145 L100 190 L24 145 L24 55 Z"
      fill="rgba(255,255,255,0.06)" stroke="rgba(255,255,255,0.15)" strokeWidth="1.5" />
    <path d="M68 76 L100 58 L100 96 L76 110 Z" fill="#60a5fa" opacity="0.9" />
    <path d="M100 96 L100 58 L132 76 L124 110 Z" fill="#8b5cf6" opacity="0.9" />
    <path d="M68 124 L76 110 L100 96 L100 142 Z" fill="#3b82f6" opacity="0.85" />
    <path d="M132 124 L100 142 L100 96 L124 110 Z" fill="#7c3aed" opacity="0.85" />
  </svg>
);

/* ── Eye icon ── */
const EyeIcon = ({ open }) => open ? (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94" />
    <path d="M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19" />
    <line x1="1" y1="1" x2="23" y2="23" />
  </svg>
) : (
  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
    <circle cx="12" cy="12" r="3" />
  </svg>
);

/* ── Styles ── */
const styles = `
  @import url('https://fonts.googleapis.com/css2?family=Sora:wght@300;400;500;600;700&family=DM+Sans:wght@300;400;500&display=swap');

  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'DM Sans', sans-serif;
    background: #0b1530;
    color: #e2e8f0;
    min-height: 100vh;
  }

  .login-layout {
    display: grid;
    grid-template-columns: 1fr 1fr;
    min-height: 100vh;
  }

  /* ── Left panel ── */
  .login-left {
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: 48px 72px;
    background: #0d1b3e;
    animation: fadeSlideUp 0.6s ease both;
  }

  @keyframes fadeSlideUp {
    from { opacity: 0; transform: translateY(24px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  .login-logo {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 48px;
    font-family: 'Sora', sans-serif;
    font-weight: 700;
    font-size: 20px;
    color: #fff;
    letter-spacing: -0.3px;
  }

  .login-title {
    font-family: 'Sora', sans-serif;
    font-size: clamp(22px, 3vw, 30px);
    font-weight: 700;
    color: #fff;
    letter-spacing: -0.5px;
    margin-bottom: 8px;
  }

  .login-subtitle {
    font-size: 15px;
    color: #7a8fb5;
    margin-bottom: 36px;
    font-weight: 400;
  }

  /* ── Form ── */
  .login-form { display: flex; flex-direction: column; gap: 0; }

  .form-group { margin-bottom: 18px; position: relative; }

  .field-label {
    display: block;
    font-size: 12px;
    font-weight: 500;
    color: #7a8fb5;
    margin-bottom: 6px;
    letter-spacing: 0.4px;
    text-transform: uppercase;
  }

  .field-wrap { position: relative; }

  .form-input {
    width: 100%;
    background: #111e40;
    border: 1.5px solid #1e3060;
    border-radius: 12px;
    color: #e2e8f0;
    font-family: 'DM Sans', sans-serif;
    font-size: 15px;
    padding: 14px 18px;
    outline: none;
    transition: border-color 0.2s, box-shadow 0.2s, background 0.2s;
  }

  .form-input::placeholder { color: #3d5080; }

  .form-input:focus {
    border-color: #3b82f6;
    background: #0f1e42;
    box-shadow: 0 0 0 3px rgba(59,130,246,0.15);
  }

  .form-input.has-value {
    border-color: #2a4a80;
    color: #c8d6f0;
  }

  .form-input.pw-input { padding-right: 48px; }

  .toggle-pw {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    cursor: pointer;
    color: #4a6090;
    display: flex;
    align-items: center;
    transition: color 0.2s;
  }
  .toggle-pw:hover { color: #7a9fd0; }

  /* ── Row ── */
  .form-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 28px;
    margin-top: 4px;
  }

  .checkbox-wrap {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    font-size: 14px;
    color: #7a8fb5;
    user-select: none;
  }

  .checkbox-wrap input[type="checkbox"] {
    width: 16px; height: 16px;
    accent-color: #3b82f6;
    cursor: pointer;
  }

  .forgot-link {
    font-size: 14px;
    color: #4a90d9;
    text-decoration: none;
    font-weight: 500;
    transition: color 0.2s;
  }
  .forgot-link:hover { color: #7ab8f5; }

  /* ── Button ── */
  .btn-login {
    width: 100%;
    padding: 15px;
    border-radius: 12px;
    border: none;
    background: linear-gradient(135deg, #2563eb 0%, #4f46e5 100%);
    color: #fff;
    font-family: 'Sora', sans-serif;
    font-size: 15px;
    font-weight: 600;
    cursor: pointer;
    letter-spacing: 0.2px;
    transition: opacity 0.2s, transform 0.15s, box-shadow 0.2s;
    box-shadow: 0 4px 20px rgba(37,99,235,0.35);
  }

  .btn-login:hover:not(:disabled) {
    opacity: 0.92;
    transform: translateY(-1px);
    box-shadow: 0 6px 28px rgba(37,99,235,0.45);
  }

  .btn-login:active:not(:disabled) { transform: translateY(0); }

  .btn-login:disabled { opacity: 0.6; cursor: not-allowed; }

  /* ── Alert ── */
  .alert {
    border-radius: 10px;
    padding: 12px 16px;
    font-size: 14px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    gap: 8px;
    animation: fadeSlideUp 0.3s ease;
  }

  .alert-error { background: rgba(220,38,38,0.12); border: 1px solid rgba(220,38,38,0.3); color: #f87171; }

  /* ── Right panel ── */
  .login-right {
    display: flex;
    align-items: center;
    justify-content: center;
    background: linear-gradient(160deg, #0b1530 0%, #0f2050 40%, #0a1828 100%);
    position: relative;
    overflow: hidden;
  }

  .right-glow {
    position: absolute;
    width: 420px; height: 420px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(59,130,246,0.18) 0%, transparent 70%);
    animation: pulse 4s ease-in-out infinite;
  }
  .right-glow-2 {
    position: absolute;
    width: 280px; height: 280px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(124,58,237,0.14) 0%, transparent 70%);
    top: 35%; left: 55%;
    animation: pulse 5s ease-in-out infinite reverse;
  }

  @keyframes pulse {
    0%, 100% { transform: scale(1); opacity: 0.7; }
    50% { transform: scale(1.08); opacity: 1; }
  }

  .brand-hex {
    position: relative;
    z-index: 1;
    animation: float 6s ease-in-out infinite;
  }

  @keyframes float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-14px); }
  }

  .brand-tagline {
    position: absolute;
    bottom: 48px;
    text-align: center;
    font-family: 'Sora', sans-serif;
    font-size: 13px;
    color: rgba(255,255,255,0.25);
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  /* ── Spinner ── */
  .spinner {
    display: inline-block;
    width: 16px; height: 16px;
    border: 2px solid rgba(255,255,255,0.3);
    border-top-color: #fff;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
    vertical-align: middle;
    margin-right: 8px;
  }
  @keyframes spin { to { transform: rotate(360deg); } }

  /* ── Responsive ── */
  @media (max-width: 900px) {
    .login-layout { grid-template-columns: 1fr; }
    .login-right { display: none; }
    .login-left { padding: 40px 32px; }
  }

  @media (max-width: 480px) {
    .login-left { padding: 32px 20px; }
    .login-title { font-size: 22px; }
    .login-logo { margin-bottom: 36px; }
  }
`;

/* ── Component ── */
const Login = () => {
  const navigate = useNavigate();
  const { login } = useAuth();

  // Pre-filled demo values matching the Figma screenshot
  const [form, setForm] = useState({ email: 'name@gmail.com', password: '1283920' });
  const [showPw, setShowPw] = useState(false);
  const [remember, setRemember] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm(f => ({ ...f, [e.target.name]: e.target.value }));
    setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.email || !form.password) {
      setError('Please enter your email and password.');
      return;
    }
    setLoading(true);
    try {
      const res = await authAPI.login({ email: form.email, password: form.password });
      login(res.data.user, res.data.token);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Login failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <style>{styles}</style>
      <div className="login-layout">

        {/* ── Left: form ── */}
        <div className="login-left">
          <div className="login-logo">
            <AlphagnitoLogo size={32} />
            <span>Alphagnito</span>
          </div>

          <h1 className="login-title">Welcome to Alphagnito</h1>
          <p className="login-subtitle">Sign in to your account</p>

          <form className="login-form" onSubmit={handleSubmit}>
            {error && (
              <div className="alert alert-error">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="10" /><line x1="12" y1="8" x2="12" y2="12" /><line x1="12" y1="16" x2="12.01" y2="16" /></svg>
                {error}
              </div>
            )}

            <div className="form-group">
              <label className="field-label">Email address</label>
              <input
                className={`form-input${form.email ? ' has-value' : ''}`}
                type="email"
                name="email"
                placeholder="name@gmail.com"
                value={form.email}
                onChange={handleChange}
                autoComplete="email"
              />
            </div>

            <div className="form-group">
              <label className="field-label">Password</label>
              <div className="field-wrap">
                <input
                  className={`form-input pw-input${form.password ? ' has-value' : ''}`}
                  type={showPw ? 'text' : 'password'}
                  name="password"
                  placeholder="Password"
                  value={form.password}
                  onChange={handleChange}
                  autoComplete="current-password"
                />
                <button
                  type="button"
                  className="toggle-pw"
                  onClick={() => setShowPw(v => !v)}
                  tabIndex={-1}
                  aria-label={showPw ? 'Hide password' : 'Show password'}
                >
                  <EyeIcon open={showPw} />
                </button>
              </div>
            </div>

            <div className="form-row">
              <label className="checkbox-wrap">
                <input
                  type="checkbox"
                  checked={remember}
                  onChange={e => setRemember(e.target.checked)}
                />
                Remember me
              </label>
              <a href="/forgot-password" className="forgot-link">Forgot password?</a>
            </div>

            <button className="btn-login" type="submit" disabled={loading}>
              {loading ? <><span className="spinner" />Signing in...</> : 'Login'}
            </button>
          </form>
        </div>

        {/* ── Right: brand visual ── */}
        <div className="login-right">
          <div className="right-glow" />
          <div className="right-glow-2" />
          <svg className="brand-hex" width="220" height="220" viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M100 10 L176 55 L176 145 L100 190 L24 145 L24 55 Z"
              fill="rgba(255,255,255,0.04)" stroke="rgba(255,255,255,0.1)" strokeWidth="1.5" />
            <path d="M68 76 L100 58 L100 96 L76 110 Z" fill="#60a5fa" opacity="0.9" />
            <path d="M100 96 L100 58 L132 76 L124 110 Z" fill="#8b5cf6" opacity="0.9" />
            <path d="M68 124 L76 110 L100 96 L100 142 Z" fill="#3b82f6" opacity="0.85" />
            <path d="M132 124 L100 142 L100 96 L124 110 Z" fill="#7c3aed" opacity="0.85" />
          </svg>
          <p className="brand-tagline">Alphagnito CRM</p>
        </div>

      </div>
    </>
  );
};

export default Login;
